======== ValidateOwnerPostcode ========
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;
import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Validates the owner's optional postcode. When present it must be 4 digits and, for a city with a
 * known region ({@link Locality}), fall within that region's range (NSW 2000-2099, VIC 3000-3099,
 * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An absent postcode is
 * left untouched, so the create contract stays backward-compatible. An invalid postcode is a 400
 * via {@link MissingOwnerFieldsException}.
 */
public class ValidateOwnerPostcode {

    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
        String postcode = owner.getPostcode();
        if (postcode == null) {
            return;
        }
        int[] range = REGION_RANGE.get(Locality.of(owner));
        if (!postcode.matches("[0-9]{4}")
                || (range != null && (Integer.parseInt(postcode) < range[0] || Integer.parseInt(postcode) > range[1]))) {
            throw new MissingOwnerFieldsException(List.of("postcode"));
        }
    }
}
======== Locality ========
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's locality from the pinned city-to-region table
 * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), or {@code UNKNOWN}
 * for any other city.
 */
public final class Locality {

    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private Locality() {
    }

    public static String of(Owner owner) {
        String byPostcode = fromPostcode(owner.getPostcode());
        if (byPostcode != null) {
            return byPostcode;
        }
        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
    }

    private static String fromPostcode(String postcode) {
        if (postcode == null || !postcode.matches("\\d{4}")) {
            return null;
        }
        int code = Integer.parseInt(postcode);
        if (code >= 2000 && code <= 2099) {
            return "NSW";
        }
        if (code >= 3000 && code <= 3099) {
            return "VIC";
        }
        if (code >= 4000 && code <= 4099) {
            return "QLD";
        }
        return null;
    }
}
======== HouseholdId ========
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives the stable identifier of an owner's household: the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode} (last name compared case-insensitively with collapsed
 * whitespace, exactly as {@link RejectDuplicateOwnerHousehold} groups them). Every owner sharing a
 * last name and postcode therefore maps to the same value without any stored state, so a household
 * is keyed on {@code (lastName, postcode)} alone.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(Owner owner) {
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        String key = normalize(owner.getLastName()) + '|' + postcode;
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder id = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                id.append(String.format("%02X", digest[i]));
            }
            return id.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
======== HouseholdSize ========
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Counts the members of an owner's household: the owners sharing this owner's {@link HouseholdId}
 * (last name and postcode). The owner itself is included, so a freshly created owner counts towards
 * its own household total.
 */
public final class HouseholdSize {

    private HouseholdSize() {
    }

    public static int of(Owner owner, OwnerRepository repository) {
        String householdId = HouseholdId.of(owner);
        int count = 0;
        for (Owner other : repository.findAll()) {
            if (householdId.equals(HouseholdId.of(other))) {
                count++;
            }
        }
        return count;
    }
}
======== IdentityKey ========
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code identityKey}: the single value duplicate detection is expressed
 * through. It is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
 * telephone is E.164 (see {@link E164Telephone}), the email is lower-cased (empty when absent) and
 * the household id groups owners by last name and address (see {@link HouseholdId}). Because the
 * telephone is part of the key, two members of one household with different telephones have
 * different keys and are both allowed; only owners that collide on the key are duplicates.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(Owner owner) {
        return telephone(owner) + '|' + email(owner) + '|' + HouseholdId.of(owner);
    }

    static String telephone(Owner owner) {
        String telephone = E164Telephone.toE164(owner.getTelephone());
        return telephone == null ? "" : telephone;
    }

    static String email(Owner owner) {
        String email = owner.getEmail();
        return (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
    }
}
